# ---------- 边缘停靠(360悬浮球风格: 平时贴边半藏露出边框, 鼠标靠近滑出, 手动拖动任意移动, 松手自动吸附最近边缘, 移开鼠标快速收回) ----------
$wa = [System.Windows.SystemParameters]::WorkArea
$script:REVEAL = 16             # 半藏时露出的边框宽度(px, 各边缘一致)
$script:MOUSE_NEAR = 30         # 鼠标距停靠边缘多少像素内触发滑出
$script:RETRACT_MS = 2000       # 滑出后鼠标移开多久自动收回(毫秒)
$script:SNAP_RANGE = 400        # 松手时窗口中心距最近边缘多少像素内自动吸附
$script:dockEdge = 'right'      # 当前停靠边缘: right/left/top/bottom
$script:edgeState = 'docked'    # docked(贴边半藏) / shown(完全显示)
$script:leaveMs = 0             # 鼠标离开累计毫秒
$script:dragging = $false       # 手动拖动标志
$script:dragOffX = 0            # 拖动时鼠标与窗口左缘的偏移
$script:dragOffY = 0            # 拖动时鼠标与窗口上缘的偏移
$window.Top = $wa.Bottom - 360  # 初始垂直位置: 右下角上方
$window.Left = $wa.Right - $script:REVEAL   # 初始: 停靠右缘, 半藏露出边框

function Dock-HidePos {
  switch ($script:dockEdge) {
    'right'  { $v = $wa.Right - $script:REVEAL;   return ,@($v, $window.Top) }
    'left'   { $v = $window.Width - $script:REVEAL; return ,@(-$v, $window.Top) }
    'top'    { $v = $window.Height - $script:REVEAL; return ,@($window.Left, -$v) }
    'bottom' { $v = $wa.Bottom - $script:REVEAL; return ,@($window.Left, $v) }
  }
}
function Dock-ShowPos {
  switch ($script:dockEdge) {
    'right'  { $v = $wa.Right - $window.Width; return ,@($v, $window.Top) }
    'left'   { return ,@(0, $window.Top) }
    'top'    { return ,@($window.Left, 0) }
    'bottom' { $v = $wa.Bottom - $window.Height; return ,@($window.Left, $v) }
  }
}
function Slide-Window {
  param($toLeft, $toTop)
  try {
    $ease = [System.Windows.Media.Animation.QuadraticEase]::new()
    $ease.EasingMode = 'EaseOut'
    $dur = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(220))
    $animL = [System.Windows.Media.Animation.DoubleAnimation]::new($window.Left, $toLeft, $dur)
    $animL.EasingFunction = $ease
    $window.BeginAnimation([System.Windows.Window]::LeftProperty, $animL)
    $animT = [System.Windows.Media.Animation.DoubleAnimation]::new($window.Top, $toTop, $dur)
    $animT.EasingFunction = $ease
    $window.BeginAnimation([System.Windows.Window]::TopProperty, $animT)
  } catch {
    # 动画失败兜底: 直接定位, 保证状态与位置同步
    try { $window.Left = $toLeft; $window.Top = $toTop } catch {}
  }
}
function Pop-Out {
  if ($script:edgeState -ne 'shown') {
    $script:edgeState = 'shown'
    # 底部停靠: 滑出时恢复置顶最上(隐藏时 Z 序已放到任务栏之下)
    if ($script:dockEdge -eq 'bottom') { Set-PetZOrder $false }
    $script:leaveMs = 0
    $pos = Dock-ShowPos
    Slide-Window $pos[0] $pos[1]
  }
}
function Retract {
  if ($script:edgeState -ne 'docked') {
    $script:edgeState = 'docked'
    # 底部停靠: 隐藏时把窗口 Z 序放到任务栏之下(被任务栏遮挡, 不覆盖任务栏; 仍保持置顶, 显示桌面不隐藏)
    if ($script:dockEdge -eq 'bottom') { Set-PetZOrder $true }
    $pos = Dock-HidePos
    Slide-Window $pos[0] $pos[1]
  }
}
# 调整窗口 Z 序: $true=放到任务栏之下(底部隐藏); $false=恢复置顶最上(弹出)
function Set-PetZOrder {
  param($belowTaskbar)
  try {
    $hw = [System.Windows.Interop.WindowInteropHelper]::new($window).Handle
    if ($hw -eq [IntPtr]::Zero) { return }
    $flags = 0x0001 -bor 0x0002 -bor 0x0010   # SWP_NOSIZE | SWP_NOMOVE | SWP_NOACTIVATE
    if ($belowTaskbar) {
      $tb = [Zz.ZOrd]::FindWindow('Shell_TrayWnd', $null)
      if ($tb -ne [IntPtr]::Zero) { [Zz.ZOrd]::SetWindowPos($hw, $tb, 0, 0, 0, 0, $flags) | Out-Null }
    } else {
      [Zz.ZOrd]::SetWindowPos($hw, [IntPtr]::new(-1), 0, 0, 0, 0, $flags) | Out-Null   # HWND_TOPMOST
    }
  } catch {}
}
# 360风格: 松手时自动吸附窗口中心最近的屏幕边缘(右/左/上/下, 露出宽度统一), 距所有边缘过远则保持自由位置
function Check-Snap {
  $cx = $window.Left + $window.Width / 2
  $cy = $window.Top + $window.Height / 2
  $dR = $wa.Right - $cx
  $dL = $cx
  $dB = $wa.Bottom - $cy
  $dT = $cy
  $dmin = [math]::Min([math]::Min($dR, $dL), [math]::Min($dB, $dT))
  if ($dmin -gt $script:SNAP_RANGE) { return $false }
  if ($dmin -eq $dR) { $script:dockEdge = 'right' }
  elseif ($dmin -eq $dL) { $script:dockEdge = 'left' }
  elseif ($dmin -eq $dB) { $script:dockEdge = 'bottom' }
  else { $script:dockEdge = 'top' }
  Retract
  return $true
}

# 手动拖动(任何状态可拖: 半藏也能直接拖出; 捕获鼠标 + 直接改坐标; 拖动中暂停边缘检测)
$window.Add_MouseLeftButtonDown({
  # 停止进行中的动画, 记录拖动偏移
  $window.BeginAnimation([System.Windows.Window]::LeftProperty, $null)
  $window.BeginAnimation([System.Windows.Window]::TopProperty, $null)
  $pt = [System.Windows.Forms.Cursor]::Position
  $script:dragOffX = $pt.X - $window.Left
  $script:dragOffY = $pt.Y - $window.Top
  $script:dragging = $true
  $script:leaveMs = 0
  try { $window.CaptureMouse() } catch {}
})
$window.Add_MouseMove({
  if ($script:dragging) {
    $pt = [System.Windows.Forms.Cursor]::Position
    $nl = $pt.X - $script:dragOffX
    $nt = $pt.Y - $script:dragOffY
    # 限制垂直范围在工作区内: 顶部不越界, 底部不覆盖任务栏(左右保留出屏, 维持甩出弹回)
    if ($nt -lt 0) { $nt = 0 }
    $maxT = $wa.Bottom - $window.Height
    if ($nt -gt $maxT) { $nt = $maxT }
    $window.Left = $nl
    $window.Top = $nt
  }
})
$window.Add_MouseLeftButtonUp({
  if ($script:dragging) {
    $script:dragging = $false
    try { $window.ReleaseMouseCapture() } catch {}
    try { Check-Snap | Out-Null } catch {}
  }
})

# 鼠标轮询(100ms): 停靠时靠近边缘滑出; 显示时移开2秒收回; 完全出屏自动弹回
$mouseTimer = [System.Windows.Threading.DispatcherTimer]::new()
$mouseTimer.Interval = [TimeSpan]::FromMilliseconds(100)
$mouseTimer.Add_Tick({
  try {
    # 拖动中: 暂停所有边缘检测与动画, 避免干扰手动拖动
    if ($script:dragging) { return }
    # 完全拖出屏幕 → 自动吸附最近边缘弹回桌面
    $outR = $window.Left -gt ($wa.Right - 4)
    $outL = ($window.Left + $window.Width - 4) -lt 0
    $outB = $window.Top -gt ($wa.Bottom - 4)
    $outT = ($window.Top + $window.Height - 4) -lt 0
    if ($outR -or $outL -or $outB -or $outT) {
      $null = Check-Snap
      if ($script:edgeState -ne 'docked') { Retract }
    } else {
      $pt = [System.Windows.Forms.Cursor]::Position
      $inWin = ($pt.X -ge $window.Left) -and ($pt.X -le ($window.Left + $window.Width)) -and `
               ($pt.Y -ge $window.Top) -and ($pt.Y -le ($window.Top + $window.Height))
      if ($script:edgeState -eq 'docked') {
        # 半藏态: 鼠标靠近当前停靠边缘(垂直/水平范围匹配窗口) → 滑出
        $near = $false
        switch ($script:dockEdge) {
          'right'  { $near = ($pt.X -ge ($wa.Right - $script:MOUSE_NEAR)) -and ($pt.Y -ge ($window.Top - 40)) -and ($pt.Y -le ($window.Top + $window.Height + 40)) }
          'left'   { $near = ($pt.X -le $script:MOUSE_NEAR) -and ($pt.Y -ge ($window.Top - 40)) -and ($pt.Y -le ($window.Top + $window.Height + 40)) }
          'top'    { $near = ($pt.Y -le $script:MOUSE_NEAR) -and ($pt.X -ge ($window.Left - 40)) -and ($pt.X -le ($window.Left + $window.Width + 40)) }
          'bottom' { $near = ($pt.Y -ge ($wa.Bottom - $script:MOUSE_NEAR)) -and ($pt.X -ge ($window.Left - 40)) -and ($pt.X -le ($window.Left + $window.Width + 40)) }
        }
        if ($near) { Pop-Out }
      } else {
        # 显示态: 鼠标在窗口内保持; 移开2秒收回
        if ($inWin) { $script:leaveMs = 0 }
        else { $script:leaveMs += 100 }
        if ($script:leaveMs -ge $script:RETRACT_MS) {
          $script:leaveMs = 0
          $showPos = Dock-ShowPos
          $atDock = ([math]::Abs($window.Left - $showPos[0]) -lt 8) -and ([math]::Abs($window.Top - $showPos[1]) -lt 8)
          if ($atDock) {
            Retract            # 在停靠显示位 → 直接收回半藏
          } else {
            $null = Check-Snap  # 自由位置 → 尝试吸附最近边缘; 过远则保持显示
          }
        }
      }
    }
  } catch {}
})
$mouseTimer.Start()

# ---------- 启动(ShowDialog: 窗口关闭即返回, 进程随之退出) ----------
Update-UI
Update-Battery
$null = $window.ShowDialog()

} catch {
  Write-ErrLog ("主逻辑异常: " + $_.Exception.ToString())
  Write-ErrLog ("位置: " + $_.InvocationInfo.PositionMessage)
  try { $state.running = $false } catch {}
} finally {
  # ---------- 清理 ----------
  try { $ps.Stop() } catch {}
  try { $runspace.Close() } catch {}
  try { Remove-Item -Path $pidFile -Force -ErrorAction SilentlyContinue } catch {}
}
